import pytest
import click
from click.testing import CliRunner

def test_runner_catch_exceptions_default():
    @click.command()
    def cli_raises():
        raise ValueError("This is an expected error.")

    runner = CliRunner()
    result = runner.invoke(cli_raises)
    assert result.exception is not None
    assert isinstance(result.exception, ValueError)

def test_runner_catch_exceptions_false_on_runner():
    @click.command()
    def cli_raises():
        raise ValueError("This is an expected error.")

    runner = CliRunner(catch_exceptions=False)
    with pytest.raises(ValueError, match="This is an expected error."):
        runner.invoke(cli_raises)

def test_runner_catch_exceptions_override_on_invoke():
    @click.command()
    def cli_raises():
        raise ValueError("This is an expected error.")

    runner = CliRunner(catch_exceptions=True)  # Should be overridden by invoke
    with pytest.raises(ValueError, match="This is an expected error."):
        runner.invoke(cli_raises, catch_exceptions=False)

import pytest
import click
from click.types import FuncParamType


class MyClass:
    def __init__(self, myvalue: str) -> None:
        self.myvalue = myvalue

    @staticmethod
    def from_str(input_str: str) -> "MyClass":
        if input_str != "works":
            raise ValueError(f"input was {input_str!r}, should be 'works'")
        return MyClass(input_str)


def test_func_param_type_value_error_message(runner):
    @click.command()
    @click.argument("mydata", type=FuncParamType(MyClass.from_str))
    def cli(mydata):
        pass

    result = runner.invoke(cli, ["fail"])

    # The bug is that it currently outputs "'fail' is not a valid value."
    # The fix should make it output the ValueError message: "input was 'fail', should be 'works'"
    assert "input was 'fail', should be 'works'" in result.output

